**1. Generalized Monitor Structure:**

```systemverilog
class my_monitor extends uvm_monitor;
  `uvm_component_utils(my_monitor)

  virtual dut_if vif;
  uvm_analysis_port #(my_item) item_port;

  function new(string name, uvm_component parent);
    super.new(name, parent);
    item_port = new("item_port", this);
  endfunction

  virtual function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    uvm_config_db#(virtual dut_if)::get(this, "", "vif", vif);
  endfunction

  virtual task run_phase(uvm_phase phase);
    forever begin
      my_item item = my_item::type_id::create("item");
      // Sample pins on clock edge
      @(posedge vif.clk iff vif.valid && vif.ready);
      item.data = vif.data;
      item.addr = vif.addr;
      // Broadcast transaction
      item_port.write(item);
    end
  endtask
endclass
```

**2. Generalized Scoreboard Structure:**

```systemverilog
class my_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(my_scoreboard)

  // Use TLM analysis exports with analysis imp
  `uvm_analysis_imp_decl(_in)
  `uvm_analysis_imp_decl(_out)

  uvm_analysis_imp_in  #(my_item, my_scoreboard) in_imp;
  uvm_analysis_imp_out #(my_item, my_scoreboard) out_imp;

  my_item exp_queue[$];

  function new(string name, uvm_component parent);
    super.new(name, parent);
    in_imp  = new("in_imp", this);
    out_imp = new("out_imp", this);
  endfunction

  virtual function void write_in(my_item item);
    // Push expected transaction into queue
    exp_queue.push_back(item);
  endfunction

  virtual function void write_out(my_item act_item);
    my_item exp_item;
    if (exp_queue.size() == 0) begin
      `uvm_error("SCB", "Unexpected output packet received!")
      return;
    end
    exp_item = exp_queue.pop_front();
    if (!act_item.compare(exp_item)) begin
      `uvm_error("SCB", "Data mismatch detected!")
    end
  endfunction
endclass
```

